<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* === ELEMENT SPEC ===
 * Carbon sphere: SphereGeometry(0.34,32,32) MeshStandardMaterial #555555
 * Substituent spheres: SphereGeometry(0.30,32,32) MeshStandardMaterial per color
 * Bonds: CylinderGeometry(0.06,0.06,1,8) MeshStandardMaterial #aaaaaa
 * Mirror pane: BoxGeometry(0.08,3.2,2.6) MeshPhysicalMaterial #cfe6f5 opacity 0.25
 * Mirror streak: PlaneGeometry(0.03,2.8) MeshBasicMaterial white additive rotated
 * Ground line: Line (-4,-1.6,0)→(4,-1.6,0) #999999
 * Wedge-dash formula: Line segments + triangle mesh at far left
 * Labels: addLabel for substituents + formula
 */

const TET_POS = [
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(-0.943, -0.333, 0),
  new THREE.Vector3(0.471, -0.333, 0.816),
  new THREE.Vector3(0.471, -0.333, -0.816)
];

const SUB_COLORS = { X: 0xb5402a, H: 0x4caf50, Y: 0x2196f3, Z: 0xd4b000 };
const SUB_LABEL_COLORS = { X: '#cc00cc', H: '#2e8b2e', Y: '#1565c0', Z: '#b8860b' };

// Lighting
const ambLight = new THREE.AmbientLight(0xffffff, 0.5);
scene.add(ambLight);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

// Molecule configurations
const MOLECULES = {
  CH3X: ['X', 'H', 'H', 'H'],
  CH2XY: ['X', 'H', 'Y', 'H'],
  CHXYZ: ['X', 'H', 'Y', 'Z']
};

let currentMolecule = 'CH3X';

// Build molecule group
function buildMoleculeGroup(subs, posX) {
  const group = new THREE.Group();
  group.position.x = posX;

  // Carbon
  const cGeo = new THREE.SphereGeometry(0.34, 32, 32);
  const cMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.4 });
  const carbon = new THREE.Mesh(cGeo, cMat);
  group.add(carbon);

  // Substituents and bonds
  for (let i = 0; i < 4; i++) {
    const sub = subs[i];
    const pos = TET_POS[i];

    // Sphere
    const sGeo = new THREE.SphereGeometry(0.30, 32, 32);
    const sMat = new THREE.MeshStandardMaterial({ color: SUB_COLORS[sub], roughness: 0.35 });
    const sphere = new THREE.Mesh(sGeo, sMat);
    sphere.position.copy(pos);
    sphere.userData.subType = sub;
    sphere.userData.slotIndex = i;
    group.add(sphere);

    // Bond cylinder
    const bGeo = new THREE.CylinderGeometry(0.06, 0.06, 1.0, 8);
    const bMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.5 });
    const bond = new THREE.Mesh(bGeo, bMat);
    bond.position.copy(pos.clone().multiplyScalar(0.5));
    bond.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), pos.clone().normalize());
    group.add(bond);
  }

  return group;
}

// Original molecule
const originalGroup = buildMoleculeGroup(MOLECULES[currentMolecule], -2.2);
scene.add(originalGroup);

// Reflected molecule (mirror image)
const reflectedGroup = buildMoleculeGroup(MOLECULES[currentMolecule], 2.2);
reflectedGroup.scale.x = -1; // This reverses handedness
scene.add(reflectedGroup);

// Store reference positions for superimposability check
let reflectedOffsetX = 2.2; // Current x-offset of reflected group
let reflectedRotY = 0; // Current Y-rotation of reflected group

// Mirror pane
const mirrorGeo = new THREE.BoxGeometry(0.08, 3.2, 2.6);
const mirrorMat = new THREE.MeshPhysicalMaterial({
  color: 0xcfe6f5,
  transparent: true,
  opacity: 0.25,
  roughness: 0.1,
  metalness: 0.1,
  side: THREE.DoubleSide
});
const mirrorPane = new THREE.Mesh(mirrorGeo, mirrorMat);
mirrorPane.position.set(0, 0, 0);
scene.add(mirrorPane);

// Mirror highlight streak
const streakGeo = new THREE.PlaneGeometry(0.03, 2.8);
const streakMat = new THREE.MeshBasicMaterial({
  color: 0xffffff,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending,
  side: THREE.DoubleSide
});
const streak = new THREE.Mesh(streakGeo, streakMat);
streak.position.set(0.05, 0, 0);
streak.rotation.z = Math.PI / 6;
scene.add(streak);

// Ground reference line
const groundPts = [new THREE.Vector3(-4.5, -1.6, 0), new THREE.Vector3(4.5, -1.6, 0)];
const groundGeo = new THREE.BufferGeometry().setFromPoints(groundPts);
const groundMat = new THREE.LineBasicMaterial({ color: 0x999999 });
const groundLine = new THREE.Line(groundGeo, groundMat);
scene.add(groundLine);

// Wedge-dash formula (2D representation at far left)
const wedgeGroup = new THREE.Group();
wedgeGroup.position.set(-4.2, 0, 0);

// C label position (center of wedge formula)
const cPos2D = new THREE.Vector3(0, 0, 0);
const lineMat = new THREE.LineBasicMaterial({ color: 0x333333 });

// Up line (to X)
const upLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([cPos2D, new THREE.Vector3(0, 0.5, 0)]),
  lineMat
);
wedgeGroup.add(upLine);

// Left line (to H)
const leftLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([cPos2D, new THREE.Vector3(-0.45, -0.25, 0)]),
  lineMat
);
wedgeGroup.add(leftLine);

// Right line (to Y/H)
const rightLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([cPos2D, new THREE.Vector3(0.45, -0.25, 0)]),
  lineMat
);
wedgeGroup.add(rightLine);

// Down wedge (to H/Y/Z) - triangle
const wedgeShape = new THREE.Shape();
wedgeShape.moveTo(0, 0);
wedgeShape.lineTo(-0.08, -0.5);
wedgeShape.lineTo(0.08, -0.5);
wedgeShape.closePath();
const wedgeGeo2D = new THREE.ShapeGeometry(wedgeShape);
const wedgeMat2D = new THREE.MeshBasicMaterial({ color: 0x333333, side: THREE.DoubleSide });
const wedgeMesh = new THREE.Mesh(wedgeGeo2D, wedgeMat2D);
wedgeGroup.add(wedgeMesh);

scene.add(wedgeGroup);

// Labels
const labelEntries = [];

function updateLabels() {
  // Remove old labels
  for (const entry of labelEntries) {
    entry.div.remove();
  }
  labelEntries.length = 0;

  const subs = MOLECULES[currentMolecule];

  // Original molecule labels
  for (let i = 0; i < 4; i++) {
    const worldPos = TET_POS[i].clone().add(new THREE.Vector3(-2.2, 0, 0));
    worldPos.y += 0.45;
    const lbl = addLabel(subs[i], worldPos, {
      color: SUB_LABEL_COLORS[subs[i]],
      bold: true,
      fontSize: '14px'
    });
    labelEntries.push(lbl);
  }

  // Reflected molecule labels
  for (let i = 0; i < 4; i++) {
    const mirrored = TET_POS[i].clone();
    mirrored.x = -mirrored.x; // Mirror
    const worldPos = mirrored.clone().add(new THREE.Vector3(reflectedOffsetX, 0, 0));
    worldPos.y += 0.45;
    const lbl = addLabel(subs[i], worldPos, {
      color: SUB_LABEL_COLORS[subs[i]],
      bold: true,
      fontSize: '14px'
    });
    labelEntries.push(lbl);
  }

  // Condensed formula label
  let formulaHTML = '';
  if (currentMolecule === 'CH3X') {
    formulaHTML = 'CH<sub>3</sub><span style="color:#cc00cc">X</span>';
  } else if (currentMolecule === 'CH2XY') {
    formulaHTML = 'CH<sub>2</sub><span style="color:#cc00cc">X</span><span style="color:#1565c0">Y</span>';
  } else {
    formulaHTML = 'CH<span style="color:#cc00cc">X</span><span style="color:#1565c0">Y</span><span style="color:#b8860b">Z</span>';
  }
  const fLbl = addLabel(formulaHTML, new THREE.Vector3(-4.2, 1.0, 0), {
    fontSize: '16px',
    bold: true
  });
  labelEntries.push(fLbl);

  // Wedge-dash labels
  const wLbls = [
    { text: subs[0], pos: new THREE.Vector3(-4.2, 0.65, 0), color: SUB_LABEL_COLORS[subs[0]] },
    { text: subs[1], pos: new THREE.Vector3(-4.75, -0.35, 0), color: SUB_LABEL_COLORS[subs[1]] },
    { text: subs[2], pos: new THREE.Vector3(-3.65, -0.35, 0), color: SUB_LABEL_COLORS[subs[2]] },
    { text: subs[3], pos: new THREE.Vector3(-4.2, -0.7, 0), color: SUB_LABEL_COLORS[subs[3]] }
  ];
  for (const wl of wLbls) {
    const l = addLabel(wl.text, wl.pos, { color: wl.color, bold: true, fontSize: '12px' });
    labelEntries.push(l);
  }
}

updateLabels();

// Molecule switching
function setMolecule(type) {
  currentMolecule = type;
  const subs = MOLECULES[type];

  // Update original
  originalGroup.children.forEach(child => {
    if (child.userData.subType !== undefined) {
      const idx = child.userData.slotIndex;
      child.material.color.setHex(SUB_COLORS[subs[idx]]);
      child.userData.subType = subs[idx];
    }
  });

  // Update reflected
  reflectedGroup.children.forEach(child => {
    if (child.userData.subType !== undefined) {
      const idx = child.userData.slotIndex;
      child.material.color.setHex(SUB_COLORS[subs[idx]]);
      child.userData.subType = subs[idx];
    }
  });

  updateLabels();
  resetReflected();
}

function resetReflected() {
  reflectedOffsetX = 2.2;
  reflectedRotY = 0;
  reflectedGroup.position.x = reflectedOffsetX;
  reflectedGroup.rotation.y = reflectedRotY;
  hideVerdict();
}

// UI buttons
document.getElementById('btnCH3X').addEventListener('click', () => {
  setMolecule('CH3X');
  document.getElementById('btnCH3X').classList.add('active');
  document.getElementById('btnCH2XY').classList.remove('active');
  document.getElementById('btnCHXYZ').classList.remove('active');
});
document.getElementById('btnCH2XY').addEventListener('click', () => {
  setMolecule('CH2XY');
  document.getElementById('btnCH2XY').classList.add('active');
  document.getElementById('btnCH3X').classList.remove('active');
  document.getElementById('btnCHXYZ').classList.remove('active');
});
document.getElementById('btnCHXYZ').addEventListener('click', () => {
  setMolecule('CHXYZ');
  document.getElementById('btnCHXYZ').classList.add('active');
  document.getElementById('btnCH3X').classList.remove('active');
  document.getElementById('btnCH2XY').classList.remove('active');
});

// Drag interaction for reflected molecule
let isDragging = false;
let dragStartX = 0, dragStartY = 0;
let dragStartOffsetX = 0, dragStartRotY = 0;

const raycasterDrag = new THREE.Raycaster();
const pointerDrag = new THREE.Vector2();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  pointerDrag.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointerDrag.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycasterDrag.setFromCamera(pointerDrag, camera);

  const hits = raycasterDrag.intersectObjects(reflectedGroup.children, true);
  if (hits.length > 0) {
    isDragging = true;
    dragStartX = e.clientX;
    dragStartY = e.clientY;
    dragStartOffsetX = reflectedOffsetX;
    dragStartRotY = reflectedRotY;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const dx = e.clientX - dragStartX;
  const dy = e.clientY - dragStartY;

  // Horizontal: translate along x
  reflectedOffsetX = Math.max(-2.2, Math.min(2.2, dragStartOffsetX - dx * 0.01));
  reflectedGroup.position.x = reflectedOffsetX;

  // Vertical: rotate about Y
  reflectedRotY = dragStartRotY + dy * 0.01;
  reflectedGroup.rotation.y = reflectedRotY;
});

canvas.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    controls.enabled = true;
    canvas.style.cursor = 'grab';
  }
});

// Superimposability check
function checkSuperimposable(rotY) {
  const subs = MOLECULES[currentMolecule];
  const tolerance = 0.15;

  // Get original substituent world positions
  const origPositions = {};
  for (let i = 0; i < 4; i++) {
    const sub = subs[i];
    const pos = TET_POS[i].clone().add(new THREE.Vector3(-2.2, 0, 0));
    if (!origPositions[sub]) origPositions[sub] = [];
    origPositions[sub].push(pos);
  }

  // Get reflected substituent world positions after rotation
  const cosR = Math.cos(rotY);
  const sinR = Math.sin(rotY);
  const reflPositions = {};
  for (let i = 0; i < 4; i++) {
    const sub = subs[i];
    const mirrored = TET_POS[i].clone();
    mirrored.x = -mirrored.x;
    // Apply Y-rotation
    const rx = mirrored.x * cosR + mirrored.z * sinR;
    const rz = -mirrored.x * sinR + mirrored.z * cosR;
    const pos = new THREE.Vector3(rx, mirrored.y, rz).add(new THREE.Vector3(-2.2, 0, 0));
    if (!reflPositions[sub]) reflPositions[sub] = [];
    reflPositions[sub].push(pos);
  }

  // Check if each reflected substituent matches an original of the same type
  let allMatch = true;
  for (const sub of Object.keys(reflPositions)) {
