let isDragging = false;
let dragStartX = 0, dragStartY = 0;
let dragStartOffsetX = 0, dragStartRotY = 0;

const raycasterDrag = new THREE.Raycaster();
const pointerDrag = new THREE.Vector2();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  pointerDrag.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  pointerDrag.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycasterDrag.setFromCamera(pointerDrag, camera);

  const hits = raycasterDrag.intersectObjects(reflectedGroup.children, true);
  if (hits.length > 0) {
    isDragging = true;
    dragStartX = e.clientX;
    dragStartY = e.clientY;
    dragStartOffsetX = reflectedOffsetX;
    dragStartRotY = reflectedRotY;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const dx = e.clientX - dragStartX;
  const dy = e.clientY - dragStartY;

  // Horizontal: translate along x
  reflectedOffsetX = Math.max(-2.2, Math.min(2.2, dragStartOffsetX - dx * 0.01));
  reflectedGroup.position.x = reflectedOffsetX;

  // Vertical: rotate about Y
  reflectedRotY = dragStartRotY + dy * 0.01;
  reflectedGroup.rotation.y = reflectedRotY;
});

canvas.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    controls.enabled = true;
    canvas.style.cursor = 'grab';
  }
});

// Superimposability check
function checkSuperimposable(rotY) {
  const subs = MOLECULES[currentMolecule];
  const tolerance = 0.15;

  // Get original substituent world positions
  const origPositions = {};
  for (let i = 0; i < 4; i++) {
    const sub = subs[i];
    const pos = TET_POS[i].clone().add(new THREE.Vector3(-2.2, 0, 0));
    if (!origPositions[sub]) origPositions[sub] = [];
    origPositions[sub].push(pos);
  }

  // Get reflected substituent world positions after rotation
  const cosR = Math.cos(rotY);
  const sinR = Math.sin(rotY);
  const reflPositions = {};
  for (let i = 0; i < 4; i++) {
    const sub = subs[i];
    const mirrored = TET_POS[i].clone();
    mirrored.x = -mirrored.x;
    // Apply Y-rotation
    const rx = mirrored.x * cosR + mirrored.z * sinR;
    const rz = -mirrored.x * sinR + mirrored.z * cosR;
    const pos = new THREE.Vector3(rx, mirrored.y, rz).add(new THREE.Vector3(-2.2, 0, 0));
    if (!reflPositions[sub]) reflPositions[sub] = [];
    reflPositions[sub].push(pos);
  }

  // Check if each reflected substituent matches an original of the same type
  let allMatch = true;
  for (const sub of Object.keys(reflPositions)) {
    const reflList = reflPositions[sub];
    const origList = origPositions[sub] || [];
    if (reflList.length !== origList.length) { allMatch = false; break; }

    // Try to match each reflected position to an original position (greedy)
    const used = new Set();
    for (const rp of reflList) {
      let found = false;
      for (let j = 0; j < origList.length; j++) {
        if (used.has(j)) continue;
        if (rp.distanceTo(origList[j]) < tolerance) {
          used.add(j);
          found = true;
          break;
        }
      }
      if (!found) { allMatch = false; break; }
    }
    if (!allMatch) break;
  }

  return allMatch;
}

