userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="btnCH3X" class="active">CH₃X</button>
<button id="btnCH2XY">CH₂XY</button>
<button id="btnCHXYZ">CHXYZ</button>
<button id="btnAutoAlign">Auto-align test</button>
<div id="verdict" style="font-size:12px;font-weight:bold;padding:4px 8px;border-radius:4px;display:none;"></div>
<div style="font-size:10px;color:#666;margin-top:4px;">Drag reflected model: horizontal = translate, vertical = rotate</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* === ELEMENT SPEC ===
 * Carbon: SphereGeometry(0.34, 24, 24) MeshStandardMaterial #555555
 * Substituent: SphereGeometry(0.30, 24, 24) MeshStandardMaterial per SUB_COLORS
 * Bond: CylinderGeometry(0.05, 0.05, 1.0, 8) MeshStandardMaterial #999999
 * Mirror: BoxGeometry(0.06, 10.5, 3.0) MeshPhysicalMaterial #cfe6f5 opacity 0.22
 * Streak: PlaneGeometry(0.04, 9.5) MeshBasicMaterial white additive rotated ~25°
 * Wedge-dash: Lines + ShapeGeometry triangle, ~1.6 units tall
 * Formula labels: addLabel 18px bold at x=-6.8
 * Wedge labels: addLabel 15px bold
 * Sphere labels: addLabel 13px bold
 * Rows: y = +3.2, 0, -3.2; Model x=-2.2; Mirror x=0; Reflection x=+2.2
 */

const ROW_Y = [3.2, 0, -3.2];
const MODEL_X = -2.2;
const REFL_X = 2.2;
const FORMULA_X = -6.8;
const WEDGE_X = -4.6;

const TET_POS = [
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(-0.943, -0.333, 0),
  new THREE.Vector3(0.471, -0.333, 0.816),
  new THREE.Vector3(0.471, -0.333, -0.816)
];

const SUB_COLORS = { X: 0xb5402a, H: 0x4caf50, Y: 0x2196f3, Z: 0xd4b000 };
const SUB_LABEL_COLORS = { X: '#cc00cc', H: '#2e8b2e', Y: '#1565c0', Z: '#b8860b' };
const MOLECULES = {
  CH3X: ['X', 'H', 'H', 'H'],
  CH2XY: ['X', 'H', 'Y', 'H'],
  CHXYZ: ['X', 'H', 'Y', 'Z']
};
const ROW_NAMES = ['CH3X', 'CH2XY', 'CHXYZ'];

// Lighting
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
keyLight.position.set(3, 5, 4);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-3, 2, -2);
scene.add(fillLight);

// State
let activeRow = 0;

// Build molecule group
function buildMolecule(subs, x, y, isReflection) {
  const group = new THREE.Group();
  group.position.set(x, y, 0);
  if (isReflection) group.scale.x = -1;

  const extra = isReflection ? { transparent: true, opacity: 0.72, side: THREE.DoubleSide } : {};

  const carbon = new THREE.Mesh(
    new THREE.SphereGeometry(0.34, 24, 24),
    new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.4, ...extra })
  );
  group.add(carbon);

  for (let i = 0; i < 4; i++) {
    const pos = TET_POS[i];
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.30, 24, 24),
      new THREE.MeshStandardMaterial({ color: SUB_COLORS[subs[i]], roughness: 0.35, ...extra })
    );
    sphere.position.copy(pos);
    sphere.userData.subType = subs[i];
    sphere.userData.slotIndex = i;
    group.add(sphere);

    const bond = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.05, 1.0, 8),
      new THREE.MeshStandardMaterial({ color: 0x999999, roughness: 0.5, ...extra })
    );
    bond.position.copy(pos.clone().multiplyScalar(0.5));
    bond.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), pos.clone().normalize());
    group.add(bond);
  }
  return group;
}

// Build all three rows
const originalGroups = [];
const reflectedGroups = [];
for (let r = 0; r < 3; r++) {
  const subs = MOLECULES[ROW_NAMES[r]];
  const orig = buildMolecule(subs, MODEL_X, ROW_Y[r], false);
  scene.add(orig);
  originalGroups.push(orig);

  const refl = buildMolecule(subs, REFL_X, ROW_Y[r], true);
  scene.add(refl);
  reflectedGroups.push(refl);
}

// Mirror pane
const mirrorPane = new THREE.Mesh(
  new THREE.BoxGeometry(0.06, 10.5, 3.0),
  new THREE.MeshPhysicalMaterial({
    color: 0xcfe6f5, transparent: true, opacity: 0.22,
    roughness: 0.1, metalness: 0.1, side: THREE.DoubleSide
  })
);
mirrorPane.position.set(0, 0, 0);
scene.add(mirrorPane);

// Mirror highlight streak
const streak = new THREE.Mesh(
  new THREE.PlaneGeometry(0.04, 9.5),
  new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.55,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide
  })
);
streak.position.set(0.04, 0, 0);
streak.rotation.z = Math.PI / 7;
scene.add(streak);

// Second thinner streak for glass effect
const streak2 = new THREE.Mesh(
  new THREE.PlaneGeometry(0.02, 8.0),
  new THREE.MeshBasicMaterial({
    color: 0xffffff, transparent: true, opacity: 0.3,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide
  })
);
streak2.position.set(0.04, 0.5, 0.4);
streak2.rotation.z = Math.PI / 6;
scene.add(streak2);

// Wedge-dash formulas for each row
for (let r = 0; r < 3; r++) {
  const wg = new THREE.Group();
  wg.position.set(WEDGE_X, ROW_Y[r], 0);
  const lm = new THREE.LineBasicMaterial({ color: 0x333333 });

  // Up line (to X)
  wg.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0.8, 0)
  ]), lm));

  // Left line (to H)
  wg.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(-0.6, -0.2, 0)
  ]), lm));

  // Right line (to pos 2)
  wg.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(0.6, -0.2, 0)
  ]), lm));

  // Down wedge (bold triangle to pos 3)
  const ws = new THREE.Shape();
  ws.moveTo(0, -0.05);
  ws.lineTo(-0.09, -0.75);
  ws.lineTo(0.09, -0.75);
  ws.closePath();
  wg.add(new THREE.Mesh(new THREE.ShapeGeometry(ws),
    new THREE.MeshBasicMaterial({ color: 0x333333, side: THREE.DoubleSide })));

  scene.add(wg);
}

// === LABELS ===

// Condensed formula labels (far left, large)
const formulaHTMLs = [
  'CH<sub>3</sub><span style="color:#cc00cc">X</span>',
  'CH<sub>2</sub><span style="color:#cc00cc">X</span><span style="color:#1565c0">Y</span>',
  'CH<span style="color:#cc00cc">X</span><span style="color:#1565c0">Y</span><span style="color:#b8860b">Z</span>'
];
for (let r = 0; r < 3; r++) {
  addLabel(formulaHTMLs[r], new THREE.Vector3(FORMULA_X, ROW_Y[r], 0), {
    fontSize: '18px', bold: true
  });
}

// Wedge-dash substituent labels
for (let r = 0; r < 3; r++) {
  const subs = MOLECULES[ROW_NAMES[r]];
  const y = ROW_Y[r];

  // C label
  addLabel('C', new THREE.Vector3(WEDGE_X + 0.18, y + 0.12, 0), {
    fontSize: '14px', bold: true
  });
  // X (top)
  addLabel(subs[0], new THREE.Vector3(WEDGE_X, y + 1.05, 0), {
    color: SUB_LABEL_COLORS[subs[0]], fontSize: '15px', bold: true
  });
  // H (left)
  addLabel(subs[1], new THREE.Vector3(WEDGE_X - 0.85, y - 0.2, 0), {
    color: SUB_LABEL_COLORS[subs[1]], fontSize: '15px', bold: true
  });
  // Pos 2 (right)
  addLabel(subs[2], new THREE.Vector3(WEDGE_X + 0.85, y - 0.2, 0), {
    color: SUB_LABEL_COLORS[subs[2]], fontSize: '15px', bold: true
  });
  // Pos 3 (down/wedge)
  addLabel(subs[3], new THREE.Vector3(WEDGE_X, y - 1.05, 0), {
    color: SUB_LABEL_COLORS[subs[3]], fontSize: '15px', bold: true
  });
}

// Ball-stick sphere labels (original molecules only)
const lblOffsets = [
  new THREE.Vector3(0, 0.5, 0),
  new THREE.Vector3(-0.5, 0, 0),
  new THREE.Vector3(0.5, 0.12, 0),
  new THREE.Vector3(0.5, -0.15, 0)
];
for (let r = 0; r < 3; r++) {
  const subs = MOLECULES[ROW_NAMES[r]];
  for (let i = 0; i < 4; i++) {
    const p = TET_POS[i].clone()
      .add(new THREE.Vector3(MODEL_X, ROW_Y[r], 0))
      .add(lblOffsets[i]);
    addLabel(subs[i], p, {
      color: SUB_LABEL_COLORS[subs[i]], fontSize: '13px', bold: true
    });
  }
}

// Ground reference lines
for (let r = 0; r < 3; r++) {
  const y = ROW_Y[r] - 1.7;
  scene.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(MODEL_X - 1.5, y, 0),
      new THREE.Vector3(REFL_X + 1.5, y, 0)
    ]),
    new THREE.LineBasicMaterial({ color: 0xdddddd })
  ));
}

// === INTERACTIONS ===

// Drag interaction for reflected molecule
let isDragging = false;
let dragStartX = 0, dragStartY = 0;
let dragStartPosX = 0, dragStartRotY = 0;
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRaycaster.setFromCamera(dragPointer, camera);

  const hits = dragRaycaster.intersectObjects(reflectedGroups[activeRow].children, true);
  if (hits.length > 0) {
    isDragging = true;
    dragStartX = e.clientX;
    dragStartY = e.clientY;
    dragStartPosX = reflectedGroups[activeRow].position.x;
    dragStartRotY = reflectedGroups[activeRow].rotation.y;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const dx = e.clientX - dragStartX;
  const dy = e.clientY - dragStartY;
  const g = reflectedGroups[activeRow];
  g.position.x = Math.max(-3.5, Math.min(4.5, dragStartPosX - dx * 0.012));
  g.rotation.y = dragStartRotY + dy * 0.012;
});

canvas.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    controls.enabled = true;
    canvas.style.cursor = 'grab';
  }
});

// Superimposability check
function checkSuperimposable(row, rotY) {
  const subs = MOLECULES[ROW_NAMES[row]];
  const tol = 0.15;
  const cos = Math.cos(rotY), sin = Math.sin(rotY);

  const reflPos = {};
  for (let i = 0; i < 4; i++) {
    const l = TET_POS[i].clone();
    l.x = -l.x; // mirror
    const rx = l.x * cos + l.z * sin;
    const rz = -l.x * sin + l.z * cos;
    const p = new THREE.Vector3(rx, l.y, rz);
    if (!reflPos[subs[i]]) reflPos[subs[i]] = [];
    reflPos[subs[i]].push(p);
  }

  const origPos = {};
  for (let i = 0; i < 4; i++) {
    if (!origPos[subs[i]]) origPos[subs[i]] = [];
    origPos[subs[i]].push(TET_POS[i].clone());
  }

  for (const sub of Object.keys(reflPos)) {
    const rl = reflPos[sub], ol = origPos[sub] || [];
    if (rl.length !== ol.length) return false;
    const used = new Set();
    for (const rp of rl) {
      let found = false;
      for (let j = 0; j < ol.length; j++) {
        if (used.has(j)) continue;
        if (rp.distanceTo(ol[j]) < tol) { used.add(j); found = true; break; }
      }
      if (!found) return false;
    }
  }
  return true;
}

// Verdict display
const verdictDiv = document.getElementById('verdict');
function showVerdict(ok) {
  verdictDiv.style.display = 'block';
  if (ok) {
    verdictDiv.textContent = '✓ Superimposable — achiral';
    verdictDiv.style.background = '#c8e6c9';
    verdictDiv.style.color = '#2e7d32';
  } else {
    verdictDiv.textContent = '✗ Non-superimposable — chiral';
    verdictDiv.style.background = '#ffcdd2';
    verdictDiv.style.color = '#c62828';
  }
}
function hideVerdict() { verdictDiv.style.display = 'none'; }

// Auto-align sweep
let autoAlignRunning = false;
document.getElementById('btnAutoAlign').addEventListener('click', () => {
  if (autoAlignRunning) return;
  autoAlignRunning = true;
  hideVerdict();

  const g = reflectedGroups[activeRow];
  g.position.x = MODEL_X;

  const btn = document.getElementById('btnAutoAlign');
  btn.textContent = 'Sweeping...';
  btn.disabled = true;

  let angle = 0;
  const speed = Math.PI / 60;
  let found = false;
  let bestAngle = 0;

  function step() {
    angle += speed;
    g.rotation.y = angle;

    if (checkSuperimposable(activeRow, angle)) {
      found = true;
      bestAngle = angle;
    }

    if (angle >= Math.PI * 2) {
      if (found) {
        g.rotation.y = bestAngle;
        showVerdict(true);
      } else {
        showVerdict(false);
      }
      autoAlignRunning = false;
      btn.textContent = 'Auto-align test';
      btn.disabled = false;
      return;
    }
    requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
});

// Molecule toggle
function setActiveRow(idx) {
  activeRow = idx;
  hideVerdict();
  // Reset all reflected groups
  for (let r = 0; r < 3; r++) {
    reflectedGroups[r].position.x = REFL_X;
    reflectedGroups[r].rotation.y = 0;
  }
  document.getElementById('btnCH3X').classList.toggle('active', idx === 0);
  document.getElementById('btnCH2XY').classList.toggle('active', idx === 1);
  document.getElementById('btnCHXYZ').classList.toggle('active', idx === 2);
}

document.getElementById('btnCH3X').addEventListener('click', () => setActiveRow(0));
document.getElementById('btnCH2XY').addEventListener('click', () => setActiveRow(1));
document.getElementById('btnCHXYZ').addEventListener('click', () => setActiveRow(2));

// Interactive tooltips
registerInteractive(mirrorPane, {
  title: 'Mirror',
  tooltip: 'Reflection plane',
  body: 'The mirror reflects each molecule, reversing left and right. This creates the enantiomer (mirror image) of the original molecule.'
});

for (let r = 0; r < 3; r++) {
  registerInteractive(reflectedGroups[r], {
    title: 'Mirror-image molecule',
    tooltip: 'Drag to translate/rotate and test superimposability',
    body: 'This is the mirror image of the original. Drag it horizontally to translate and vertically to rotate. If all colored spheres can be aligned with the original, the molecule is achiral (superimposable).'
  });
}

// Camera view — near-front-on perspective matching the source
setCameraView({
  projection: 'perspective',
  azimuthDeg: 12,
  elevationDeg: 8,
  rollDeg: 0,
  heightFraction: 0.62
});
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
